CREATE TABLE IF NOT EXISTS wallet_accounts (user_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,balance DECIMAL(12,2) NOT NULL DEFAULT 0.00,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_wallet_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS wallet_transactions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,type VARCHAR(30) NOT NULL,amount DECIMAL(12,2) NOT NULL,description VARCHAR(255) NOT NULL DEFAULT '',reference VARCHAR(120) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_wallet_tx_user_date (user_id,created_at),UNIQUE KEY uq_wallet_reference (reference),CONSTRAINT fk_wallet_tx_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS wallet_deposits (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(12,2) NOT NULL,reference VARCHAR(120) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'pending',provider VARCHAR(40) NOT NULL DEFAULT 'unconfigured',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,paid_at TIMESTAMP NULL,KEY idx_deposits_user (user_id,created_at),CONSTRAINT fk_deposit_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS oxb_orders (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,category VARCHAR(40) NOT NULL,product_id VARCHAR(120) NOT NULL,title VARCHAR(190) NOT NULL,amount DECIMAL(12,2) NOT NULL,provider_service_id VARCHAR(120) NULL,provider_invoice_id VARCHAR(120) NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',metadata_json LONGTEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_oxb_orders_user_date (user_id,created_at),CONSTRAINT fk_oxb_order_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
